const fs=require('node:fs'),path=require('node:path');const db=require('../services/db');const {DatabaseVectorStore}=require('../services/databaseVectorStore');
(async()=>{if(db.dialect!=='postgres'||process.env.APPROVED_BOOTSTRAP!=='yes')throw Error('Explicit approved PostgreSQL bootstrap target required');const store=new DatabaseVectorStore();if(await store.count())throw Error('Refusing to overwrite existing knowledge');const records=require('../services/bootstrapKnowledge').records;store.validate(records);await store.upsert(records);if(await store.count()!==records.length)throw Error('Bootstrap count mismatch');console.log('Verified records: '+records.length);await db.close();})().catch(()=>{console.error('Knowledge bootstrap failed; existing knowledge was not intentionally replaced');process.exitCode=1;});
